[package]
name = "clipper2_test1"
version = "0.1.0"
edition = "2021"
description = "Pure-Rust (std-only) re-implementation of the Clipper2Lib subset exercised by tests/test1.cpp"
publish = false

# Library code, organized into modules under src/.
[lib]
name = "clipper2"
path = "src/lib.rs"

# The entry test file lives in the package root, as required, and pulls the
# library modules in via `#[path = "src/lib.rs"] mod clipper2;` so that the very
# same file also compiles standalone with `rustc test1.rs`. Because the modules
# are inlined that way, the bin needs no test harness of its own — `cargo test`
# exercises the identical code through the lib target.
[[bin]]
name = "test1"
path = "test1.rs"
test = false

# Zero external dependencies: std only.
[dependencies]

[profile.release]
opt-level = 3
=== test1.rs ===
//! Rust port of `Clipper/tests/test1.cpp`.
//!
//! Entry point for the migrated test. Build it either way:
//!
//! ```text
//! rustc -O test1.rs -o test1     # standalone, no Cargo needed
//! cargo build --release          # -> target/release/test1
//! ```
//!
//! The C++ original is reproduced verbatim in behaviour: construct the
//! four-point `Path64` literal, stream its `size()` followed by `std::endl`, and
//! return 0. Command-line arguments are accepted and ignored, exactly as the C++
//! `main(int argc, char* argv[])` does — it declares them and never reads them,
//! so there are no option names, defaults, or required fields to honour, and no
//! input can change the output or the exit status.

// The library lives in `src/`, split into modules; this `#[path]` declaration is
// what lets the one entry file serve as both the Cargo bin target and a
// standalone `rustc test1.rs` translation unit.
#[path = "src/lib.rs"]
mod clipper2;

// Re-exported rather than plainly imported so that the crate root offers the
// same `crate::Path64` / `crate::Point64` names the library root does, which is
// what `$crate`-qualified macros such as `path64!` expand to.
pub use clipper2::{Path64, Point64};

use std::io::Write;

fn main() {
    // `int main(int argc, char* argv[])` — the parameters exist but are unused.
    // Collected here so the port genuinely accepts the same command line rather
    // than merely tolerating it; nothing downstream depends on the contents.
    let _args: Vec<String> = std::env::args().collect();

    // 最简单的测试：创建一个点并输出
    // (Simplest possible test: build the points and print.)
    // C++: Path64 path = {Point64(0,0), Point64(100,0), Point64(100,100), Point64(0,100)};
    let path = Path64::from(vec![
        Point64::new(0, 0),
        Point64::new(100, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ]);

    // 调用1个API：创建多边形
    // (One API call: the polygon's point count.)
    // C++: std::cout << path.size() << std::endl;
    //
    // `size()` is a `usize`, which formats as unsigned decimal with no padding,
    // grouping, or sign — identical to how `std::ostream` renders `size_t`. The
    // trailing newline is `std::endl`'s, and `flush` below is its flush.
    //
    // This is the `println!("{}", path.size())` formatting path written against a
    // locked handle so that write errors can be *discarded* rather than raised.
    // That difference is deliberate and observable: `println!` panics if the
    // write fails, which would exit 101 and print to stderr, whereas a failing
    // `std::cout` merely sets `badbit` and lets `main` still `return 0`. Compare
    // `./test1 > /dev/full` or `./test1 | head -c 0` between the two binaries —
    // with `println!` they diverge, and this way they agree.
    let mut out = std::io::stdout().lock();
    let _ = writeln!(out, "{}", path.size());

    // `std::endl` flushes too; errors ignored for the same reason as above.
    let _ = out.flush();

    // C++: return 0;  (Rust returns EXIT_SUCCESS when `main` falls off the end.)
}

  1	//! Point types.
  2	//!
  3	//! Mirrors `Clipper2Lib::Point<T>`, of which `Point64` (64-bit integer
  4	//! coordinates) is the instantiation used by `test1.cpp`. `PointD` (double
  5	//! coordinates) is provided alongside it because the C++ header exposes the two
  6	//! as a pair and callers routinely convert between them.
  7	
  8	use std::fmt;
  9	use std::ops::{Add, Neg, Sub};
 10	
 11	/// A point with 64-bit signed integer coordinates.
 12	///
 13	/// The C++ counterpart is `Clipper2Lib::Point64`, a plain aggregate of two
 14	/// `int64_t` fields, constructed as `Point64(x, y)`.
 15	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
 16	pub struct Point64 {
 17	    pub x: i64,
 18	    pub y: i64,
 19	}
 20	
 21	impl Point64 {
 22	    /// The origin, `(0, 0)` — equivalent to the default-constructed `Point64()`.
 23	    pub const ORIGIN: Self = Self { x: 0, y: 0 };
 24	
 25	    /// Constructs a point, matching the C++ `Point64(x, y)` constructor.
 26	    #[inline]
 27	    pub const fn new(x: i64, y: i64) -> Self {
 28	        Self { x, y }
 29	    }
 30	
 31	    /// Rounds a floating-point pair to the nearest integer point, halves away
 32	    /// from zero (`0.5 -> 1`, `-0.5 -> -1`), matching [`f64::round`].
 33	    ///
 34	    /// Half-away-from-zero is chosen because it is what C's `llround` family
 35	    /// specifies, which is the conventional way to narrow a `double` coordinate
 36	    /// to an integer one. Unlike `llround`, the conversion here is total: a NaN
 37	    /// input yields `0` and out-of-range inputs clamp to `i64::MIN`/`i64::MAX`,
 38	    /// which is Rust's defined behaviour for a float-to-int cast, rather than
 39	    /// C++'s unspecified result.
 40	    #[inline]
 41	    pub fn from_rounded(x: f64, y: f64) -> Self {
 42	        Self::new(x.round() as i64, y.round() as i64)
 43	    }
 44	
 45	    /// Translates the point by `(dx, dy)`.
 46	    #[inline]
 47	    pub fn translate(self, dx: i64, dy: i64) -> Self {
 48	        Self::new(self.x + dx, self.y + dy)
 49	    }
 50	
 51	    /// Widens the point to floating-point coordinates.
 52	    #[inline]
 53	    pub fn to_point_d(self) -> PointD {
 54	        PointD::new(self.x as f64, self.y as f64)
 55	    }
 56	}
 57	
 58	impl From<(i64, i64)> for Point64 {
 59	    #[inline]
 60	    fn from((x, y): (i64, i64)) -> Self {
 61	        Self::new(x, y)
 62	    }
 63	}
 64	
 65	impl From<Point64> for (i64, i64) {
 66	    #[inline]
 67	    fn from(p: Point64) -> Self {
 68	        (p.x, p.y)
 69	    }
 70	}
 71	
 72	impl Add for Point64 {
 73	    type Output = Self;
 74	    #[inline]
 75	    fn add(self, rhs: Self) -> Self {
 76	        Self::new(self.x + rhs.x, self.y + rhs.y)
 77	    }
 78	}
 79	
 80	impl Sub for Point64 {
 81	    type Output = Self;
 82	    #[inline]
 83	    fn sub(self, rhs: Self) -> Self {
 84	        Self::new(self.x - rhs.x, self.y - rhs.y)
 85	    }
 86	}
 87	
 88	impl Neg for Point64 {
 89	    type Output = Self;
 90	    #[inline]
 91	    fn neg(self) -> Self {
 92	        Self::new(-self.x, -self.y)
 93	    }
 94	}
 95	
 96	/// Renders the point as `x,y`.
 97	///
 98	/// Note: this is this crate's own convention for diagnostics. `test1.cpp` never
 99	/// streams a `Point64`, so no claim is made here about byte-compatibility with
100	/// the C++ `operator<<`; only [`Path64::size`](crate::path::Path64::size) output
101	/// is contractually reproduced.
102	impl fmt::Display for Point64 {
103	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
104	        write!(f, "{},{}", self.x, self.y)
105	    }
106	}
107	
108	/// A point with `f64` coordinates — the C++ `Clipper2Lib::PointD`.
109	#[derive(Clone, Copy, Debug, Default, PartialEq)]
110	pub struct PointD {
111	    pub x: f64,
112	    pub y: f64,
113	}
114	
115	impl PointD {
116	    /// Constructs a point, matching the C++ `PointD(x, y)` constructor.
117	    #[inline]
118	    pub const fn new(x: f64, y: f64) -> Self {
119	        Self { x, y }
120	    }
121	
122	    /// Rounds to the nearest [`Point64`], half away from zero.
123	    #[inline]
124	    pub fn to_point64(self) -> Point64 {
125	        Point64::from_rounded(self.x, self.y)
126	    }
127	}
128	
129	impl From<(f64, f64)> for PointD {
130	    #[inline]
131	    fn from((x, y): (f64, f64)) -> Self {
132	        Self::new(x, y)
133	    }
134	}
135	
136	impl From<Point64> for PointD {
137	    #[inline]
138	    fn from(p: Point64) -> Self {
139	        p.to_point_d()
140	    }
141	}
142	
143	#[cfg(test)]
144	mod tests {
145	    use super::*;
146	
147	    #[test]
148	    fn new_stores_coordinates_verbatim() {
149	        let p = Point64::new(100, -100);
150	        assert_eq!((p.x, p.y), (100, -100));
151	        assert_eq!(Point64::default(), Point64::ORIGIN);
152	    }
153	
154	    #[test]
155	    fn equality_is_componentwise() {
156	        assert_eq!(Point64::new(0, 0), Point64::from((0, 0)));
157	        assert_ne!(Point64::new(0, 1), Point64::new(1, 0));
158	    }
159	
160	    #[test]
161	    fn arithmetic_matches_cpp_operators() {
162	        let a = Point64::new(3, 4);
163	        let b = Point64::new(10, 20);
164	        assert_eq!(a + b, Point64::new(13, 24));
165	        assert_eq!(b - a, Point64::new(7, 16));
166	        assert_eq!(-a, Point64::new(-3, -4));
167	        assert_eq!(a.translate(-3, -4), Point64::ORIGIN);
168	    }
169	
170	    #[test]
171	    fn rounding_is_half_away_from_zero() {
172	        assert_eq!(Point64::from_rounded(0.5, -0.5), Point64::new(1, -1));
173	        assert_eq!(Point64::from_rounded(1.4, -1.6), Point64::new(1, -2));
174	        assert_eq!(PointD::new(2.5, 3.5).to_point64(), Point64::new(3, 4));
175	    }
176	
177	    #[test]
178	    fn rounding_is_total_for_nan_and_out_of_range() {
179	        // Rust's float-to-int cast is saturating and NaN-to-zero, so unlike
180	        // `llround` these cases are defined rather than unspecified.
181	        assert_eq!(Point64::from_rounded(f64::NAN, f64::NAN), Point64::ORIGIN);
182	        assert_eq!(
183	            Point64::from_rounded(f64::INFINITY, f64::NEG_INFINITY),
184	            Point64::new(i64::MAX, i64::MIN)
185	        );
186	        assert_eq!(Point64::from_rounded(1e300, -1e300), Point64::new(i64::MAX, i64::MIN));
187	    }
188	
189	    #[test]
190	    fn conversions_round_trip() {
191	        let p = Point64::new(100, 100);
192	        assert_eq!(PointD::from(p).to_point64(), p);
193	        assert_eq!(<(i64, i64)>::from(p), (100, 100));
194	    }
195	
196	    #[test]
197	    fn display_is_comma_separated() {
198	        assert_eq!(Point64::new(100, 0).to_string(), "100,0");
199	    }
200	}

  1	//! Path (point-sequence) containers.
  2	//!
  3	//! In the C++ header these are `std::vector` aliases:
  4	//!
  5	//! ```cpp
  6	//! template <typename T> using Path  = std::vector<Point<T>>;
  7	//! template <typename T> using Paths = std::vector<Path<T>>;
  8	//! using Path64  = Path<int64_t>;
  9	//! using Paths64 = Paths<int64_t>;
 10	//! ```
 11	//!
 12	//! `test1.cpp` relies on exactly two vector behaviours: brace-initialisation
 13	//! from a point list, and `size()` returning the number of points held. Both are
 14	//! reproduced here, with the rest of the vector-like surface delegated to the
 15	//! wrapped [`Vec`].
 16	
 17	use super::point::{PointD, Point64};
 18	use super::rect::Rect64;
 19	use std::fmt;
 20	// In the prelude only from edition 2021 onward; imported explicitly so this file
 21	// also compiles when rustc defaults to an older edition.
 22	use std::iter::FromIterator;
 23	use std::ops::{Deref, DerefMut};
 24	
 25	/// Builds a [`Path64`] from a point list, mirroring C++ brace-initialisation.
 26	///
 27	/// ```ignore
 28	/// // C++: Path64 path = {Point64(0,0), Point64(100,0)};
 29	/// let path = path64![(0, 0), (100, 0)];
 30	/// ```
 31	///
 32	/// The expansion names the types as `$crate::Path64` / `$crate::Point64`, i.e.
 33	/// through the crate-root re-exports, so it resolves the same whether this file
 34	/// is the crate root of the `clipper2` library or is pulled into `test1.rs` as a
 35	/// module for the standalone `rustc` build.
 36	#[macro_export]
 37	macro_rules! path64 {
 38	    () => { $crate::Path64::new() };
 39	    ($(($x:expr, $y:expr)),+ $(,)?) => {
 40	        $crate::Path64::from(vec![$($crate::Point64::new($x, $y)),+])
 41	    };
 42	    ($($p:expr),+ $(,)?) => {
 43	        $crate::Path64::from(vec![$($p),+])
 44	    };
 45	}
 46	
 47	/// An ordered sequence of [`Point64`]s — the C++ `Path64`.
 48	///
 49	/// A newtype over `Vec<Point64>` rather than a bare alias, so that the C++
 50	/// spelling of the vector interface (`size`, `empty`, `push_back`, …) can be
 51	/// offered verbatim. [`Deref`]/[`DerefMut`] to `Vec<Point64>` keep the whole
 52	/// standard vector surface (indexing, iteration, `sort`, …) available too.
 53	#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
 54	pub struct Path64(Vec<Point64>);
 55	
 56	impl Path64 {
 57	    /// An empty path — the default-constructed `Path64()`.
 58	    #[inline]
 59	    pub const fn new() -> Self {
 60	        Self(Vec::new())
 61	    }
 62	
 63	    /// An empty path with room for `n` points, as `std::vector::reserve` gives.
 64	    #[inline]
 65	    pub fn with_capacity(n: usize) -> Self {
 66	        Self(Vec::with_capacity(n))
 67	    }
 68	
 69	    /// Number of points in the path — the C++ `size()`.
 70	    ///
 71	    /// This is the single value `test1.cpp` prints, so it is the one result that
 72	    /// must match the C++ program byte for byte once formatted.
 73	    #[inline]
 74	    pub fn size(&self) -> usize {
 75	        self.0.len()
 76	    }
 77	
 78	    /// Whether the path holds no points — the C++ `empty()`.
 79	    #[inline]
 80	    pub fn empty(&self) -> bool {
 81	        self.0.is_empty()
 82	    }
 83	
 84	    /// Appends a point — the C++ `push_back()`.
 85	    #[inline]
 86	    pub fn push_back(&mut self, p: Point64) {
 87	        self.0.push(p);
 88	    }
 89	
 90	    /// Borrows the points as a slice.
 91	    #[inline]
 92	    pub fn points(&self) -> &[Point64] {
 93	        &self.0
 94	    }
 95	
 96	    /// Consumes the path, yielding the underlying vector.
 97	    #[inline]
 98	    pub fn into_vec(self) -> Vec<Point64> {
 99	        self.0
100	    }
101	
102	    /// Axis-aligned bounding box, or `None` when the path is empty.
103	    ///
104	    /// `None` is deliberate: the C++ library encodes "no bounds" with a sentinel
105	    /// rectangle, and reproducing that sentinel is not derivable from the public
106	    /// interface, so this crate declines to invent one.
107	    pub fn bounds(&self) -> Option<Rect64> {
108	        Rect64::from_points(&self.0)
109	    }
110	
111	    /// Twice the signed area of the closed polygon described by the path.
112	    ///
113	    /// The doubled value is returned so the shoelace sum stays exact in integer
114	    /// arithmetic. Positive when the ring winds clockwise on screen (y growing
115	    /// downward), negative when it winds the other way.
116	    ///
117	    /// Accumulation is in `i128`, which is exact for every coordinate range the
118	    /// C++ library admits. It is *not* wide enough for arbitrary full-range
119	    /// `i64` coordinates — a single cross term can reach `2 * i64::MAX²`, which
120	    /// alone nearly fills an `i128` — so the sum saturates at the `i128` bounds
121	    /// instead of panicking in debug builds and wrapping to a wrong value in
122	    /// release builds.
123	    pub fn signed_area2(&self) -> i128 {
124	        let n = self.0.len();
125	        if n < 3 {
126	            return 0;
127	        }
128	        let mut acc: i128 = 0;
129	        let mut prev = self.0[n - 1];
130	        for &cur in &self.0 {
131	            let cross = (prev.x as i128 * cur.y as i128) - (cur.x as i128 * prev.y as i128);
132	            acc = acc.saturating_add(cross);
133	            prev = cur;
134	        }
135	        acc
136	    }
137	
138	    /// Signed area of the closed polygon, in square units.
139	    #[inline]
140	    pub fn area(&self) -> f64 {
141	        self.signed_area2() as f64 / 2.0
142	    }
143	
144	    /// Widens every coordinate, producing the `PathD` counterpart.
145	    pub fn to_path_d(&self) -> PathD {
146	        PathD::from(self.0.iter().map(|p| p.to_point_d()).collect::<Vec<_>>())
147	    }
148	}
149	
150	impl Deref for Path64 {
151	    type Target = Vec<Point64>;
152	    #[inline]
153	    fn deref(&self) -> &Self::Target {
154	        &self.0
155	    }
156	}
157	
158	impl DerefMut for Path64 {
159	    #[inline]
160	    fn deref_mut(&mut self) -> &mut Self::Target {
161	        &mut self.0
162	    }
163	}
164	
165	impl From<Vec<Point64>> for Path64 {
166	    #[inline]
167	    fn from(points: Vec<Point64>) -> Self {
168	        Self(points)
169	    }
170	}
171	
172	impl From<Path64> for Vec<Point64> {
173	    #[inline]
174	    fn from(path: Path64) -> Self {
175	        path.0
176	    }
177	}
178	
179	impl<const N: usize> From<[Point64; N]> for Path64 {
180	    #[inline]
181	    fn from(points: [Point64; N]) -> Self {
182	        Self(points.to_vec())
183	    }
184	}
185	
186	impl FromIterator<Point64> for Path64 {
187	    #[inline]
188	    fn from_iter<I: IntoIterator<Item = Point64>>(iter: I) -> Self {
189	        Self(iter.into_iter().collect())
190	    }
191	}
192	
193	impl IntoIterator for Path64 {
194	    type Item = Point64;
195	    type IntoIter = std::vec::IntoIter<Point64>;
196	    #[inline]
197	    fn into_iter(self) -> Self::IntoIter {
198	        self.0.into_iter()
199	    }
200	}
201	
202	impl<'a> IntoIterator for &'a Path64 {
203	    type Item = &'a Point64;
204	    type IntoIter = std::slice::Iter<'a, Point64>;
205	    #[inline]
206	    fn into_iter(self) -> Self::IntoIter {
207	        self.0.iter()
208	    }
209	}
210	
211	impl fmt::Display for Path64 {
212	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
213	        for (i, p) in self.0.iter().enumerate() {
214	            if i > 0 {
215	                f.write_str(" ")?;
216	            }
217	            write!(f, "{p}")?;
218	        }
219	        Ok(())
220	    }
221	}
