223	/// A sequence of [`Path64`]s — the C++ `Paths64`.
224	#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
225	pub struct Paths64(Vec<Path64>);
226	
227	impl Paths64 {
228	    /// An empty collection.
229	    #[inline]
