332	/// A sequence of [`PathD`]s — the C++ `PathsD`.
333	#[derive(Clone, Debug, Default, PartialEq)]
334	pub struct PathsD(Vec<PathD>);
335	
336	impl PathsD {
337	    /// An empty collection.
338	    #[inline]
